package android.content; public class IntentFilter {private final String action;private String scheme;public IntentFilter(String a){action=a;}public void addDataScheme(String s){scheme=s;}public String action(){return action;}public boolean matches(Intent i){return action.equals(i.getAction())&&(scheme==null?i.getData()==null:i.getData()!=null&&scheme.equals(i.getData().getScheme()));}}
